out={k:P[k] for k in ['schema_version','path_id','batch_id']};out['kind']='screens_part';out['tiles']=[]
for t in P['tiles']:
 names=[bs[c]['context']['concept_name'] for c in t['concept_ids']]
 tile={'tile_id':t['tile_id'],'title':' / '.join(names),'steps':[],'remediation_steps':[]}
 for s in t['steps']:
  l=lin(s);st={'step_id':s['step_id'],'type':s['type'],'concept_ids':s['concept_ids'],'lineage':l}
  if s['type']=='explainer':
   title,text=copy_by_step[s['step_id'].removeprefix('tile_')];st['title']=title
   st['blocks']=[prose(x,l) for x in text.split('||')]
   if s['planned_visual_block_type']:
    v=copy.deepcopy(visuals[s['concept_ids'][0]]);v=v if isinstance(v,list) else [v]
    for b in v:b['lineage']=copy.deepcopy(l)
    st['blocks']+=v
  elif s['type']=='video':st.update(title='Review the core rule',blocks=[{'type':'media_group','segment_ids':s['segment_ids']}])
  elif s['type'] in ['check','hands_on']:
   st['title']=('Check: ' if s['type']=='check' else 'Practice: ')+bs[s['concept_ids'][0]]['context']['concept_name']
   st['eyebrow']='Check your understanding' if s['type']=='check' else 'Apply the contract'
  else:
   st['title']='Keep these distinctions';st['blocks']=[]
   for c in s['concept_ids']:
    first=bs[c]['teaching_notes'][0].split(': ',1)[1].rstrip('.')+'.'
    fs=[c+'#'+f['id'] for f in bs[c]['coverage']['required_facts']]
    st['blocks'].append(prose(first,{'concept_ids':[c],'teaching_block_ids':tb_for_facts(c,fs),'fact_ids':fs},'takeaway'))
   nt=next((x for x in P['tiles'] if x['tile_id']==t['next_tile_id']),None)
   text=('Next: '+bs[nt['concept_ids'][0]]['teaching_notes'][0].split(': ',1)[1]) if nt else 'Continue to '+t['next_tile_id']+'.'
   st['blocks'].append({'type':'up_next','title':'Up next: '+t['next_tile_id'],'text':text})
  tile['steps'].append(st)
 # One target per distinct measured fact set. Identical checks/practices can share the target.
 seen=set()
 for s in t['steps']:
  if s['type'] not in ['check','hands_on']:continue
  for c in s['concept_ids']:
   fs=[f for f in s['fact_ids'] if f.startswith(c+'#')]
   if not fs:
    caps=[a.split('#assessment:',1)[1] for a in s['anchors'] if '#assessment:' in a]
    ids=[f for a in bs[c]['assessment_anchors'] if a['capability'] in caps for f in a['fact_ids']]
    fs=list(dict.fromkeys(c+'#'+f for f in ids))
   if not fs:continue
   key=(c,tuple(sorted(fs)))
   if key in seen:continue
   seen.add(key)
   rid=t['tile_id']+f'.r{len(tile["remediation_steps"])+1:02d}'
   tl={'concept_ids':[c],'fact_ids':fs,'teaching_block_ids':tb_for_facts(c,fs)}
   blocks=[]
   for f in fs:
    fact=next(x for x in bs[c]['coverage']['required_facts'] if x['id']==f.split('#')[1])
    fl={'concept_ids':[c],'fact_ids':[f],'teaching_block_ids':tb_for_facts(c,[f])}
    blocks.append(prose(fact['statement'],fl))
   # The contrast comes from the concept's glossary misconception, tied to this workspace.
   contrast=next(x for x in reversed(bs[c]['teaching_blocks']) if x['purpose']=='misconception')
   cl={'concept_ids':[c],'fact_ids':[c+'#'+f for f in contrast['fact_ids']],'teaching_block_ids':[c+'#'+contrast['id']]}
   blocks.append(prose('In the same orders-service exercise: '+contrast['content'],cl,'misconception'))
   tile['remediation_steps'].append({'step_id':rid,'type':'remediation','concept_ids':[c],'title':'Revisit: '+bs[c]['context']['concept_name'],'lede':'Contrast for '+s['step_id'],'lineage':tl,'blocks':blocks})
 out['tiles'].append(tile)
(B/'screens.json').write_text(json.dumps(out,indent=2,ensure_ascii=False)+'\n')
print('Wrote',len(out['tiles']),'tiles;',sum(len(t['steps']) for t in out['tiles']),'planned steps;',sum(len(t['remediation_steps']) for t in out['tiles']),'remediation steps')
